pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint8 reverterSeed) public {
        // Keep amount reasonable to avoid overflow in deposit
        amount = bound(amount, 1, 1000 ether);
        // reverterSeed ensures fuzzer can generate different reverter addresses across runs
        vm.assume(reverterSeed > 0);

        // Deploy the adversarial helper that always reverts on receive
        address attacker = address(new Reverter());

        // Fund and credit the attacker via deposit
        vm.deal(address(this), amount);
        vm.prank(attacker);
        c.deposit{value: amount}();

        // Record pre-state: credit and contract balance
        uint256 creditBefore = c.credit(attacker);
        uint256 contractBalanceBefore = address(c).balance;
        bool success = true;
        vm.prank(attacker);
        try c.withdrawAll() {
            success = true;
        } catch {
            success = false;
        }

        uint256 creditAfter = c.credit(attacker);
        uint256 contractBalanceAfter = address(c).balance;

        // GENERAL RULE that holds for reference but bug breaks:
        // If the external call fails (Reverter reverts), the withdrawal must revert entirely,
        // leaving credit and balance unchanged. The bug silently clears credit and reduces balance.
        // Formally: after withdrawAll, if the user's credit is 0, then the user MUST have received
        // the ETH (contract balance decreased by exactly the pre-credit amount and success was true).
        // Conversely, if the call failed, credit must remain > 0 and balance unchanged.
        bool invariant = (creditAfter == 0)
            ? (success && contractBalanceAfter == contractBalanceBefore - creditBefore)
            : (!success && creditAfter == creditBefore && contractBalanceAfter == contractBalanceBefore);

        assertTrue(invariant);
    }
}

