        // But attacker is the real actor; we need failingReceiver to have credit. We can deposit from attacker and then transfer credit?
        // Credit is tied to msg.sender; to have failingReceiver call withdrawAll, it must have its own credit.
        // So we deposit from failingReceiver: we need to prank it and give it Ether.
        vm.stopPrank();

        vm.deal(failingReceiver, amount);
        vm.prank(failingReceiver);
        c.deposit{value: amount}();

        // Record reference state before withdrawal: credit of failingReceiver, total balance
        uint256 creditBefore = c.credit(failingReceiver);
        uint256 balanceBefore = address(c).balance;

